#include <string>
#include <cmath>

class Solution {
public:
    std::string resultingString(std::string s) {
        std::string st = "";
        for (char c : s) {
            if (!st.empty() && (std::abs(st.back() - c) == 1 || std::abs(st.back() - c) == 25)) {
                st.pop_back();
            } else {
                st.push_back(c);
            }
        }
        return st;
    }
};

class Solution {
    public String resultingString(String s) {
        StringBuilder st = new StringBuilder();
        for (int i = 0; i < s.length(); ++i) {
            char c = s.charAt(i);
            int len = st.length();
            if (len > 0) {
                int diff = Math.abs(st.charAt(len - 1) - c);
                if (diff == 1 || diff == 25) {
                    st.deleteCharAt(len - 1);
                    continue;
                }
            }
            st.append(c);
        }
        return st.toString();
    }
}

