var resultingString = function(s) {
    const st = [];
    for (const c of s) {
        if (st.length > 0) {
            const diff = Math.abs(st[st.length - 1].charCodeAt(0) - c.charCodeAt(0));
            if (diff === 1 || diff === 25) {
                st.pop();
                continue;
            }
        }
        st.push(c);
    }
    return st.join('');
};
